# Analyze connected components for each color
from collections import defaultdict

def get_connected_components(grid, start_color):
    """Get all connected components of a specific color"""
    visited = set()
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == start_color and (r, c) not in visited:
                comp = []
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        comp.append((cr, cc))
                        # Check neighbors
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                                if grid[nr][nc] == start_color and (nr, nc) not in visited:
                                    queue.append((nr, nc))
                components.append(comp)
    return components

# Get components for each non-background color
background = 5
for color in [0, 2, 8]:
    comps = get_connected_components(grid, color)
    print(f"\nColor {color} components:")
    for i, comp in enumerate(comps):
        rows = sorted([r for r, c in comp])
        cols = sorted([c for r, c in comp])
        print(f"  Component {i}: {len(comp)} cells, rows={rows[0]}-{rows[-1]}, cols={cols[0]}-{cols[-1]}")

# Let me try to identify bounding boxes and see if they're mostly filled
from collections import defaultdict

def get_bbox_and_fill_ratio(grid, color):
    """Get bounding box and fill ratio for each connected component"""
    positions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                positions.append((r, c))

    if not positions:
        return []

    result = []
    for comp_id, group in enumerate(defaultdict(list, {(None, None): set()}).values()):
        pass

    # Group into connected components first
    visited = set()
    components = []
    for pos in positions:
        if pos not in visited:
            comp = []
            queue = [pos]
            while queue:
                cr, cc = queue.pop(0)
                if (cr, cc) not in visited:
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))
            components.append(comp)

    bbox_info = []
    for i, comp in enumerate(components):
        rows = [r for r, c in comp]
        cols = [c for r, c in comp]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)
        total_cells = (max_r - min_r + 1) * (max_c - min_c + 1)
        actual_cells = len(comp)
        fill_ratio = actual_cells / total_cells
        bbox_info.append({
            'id': i,
            'positions': comp,
            'bbox': (min_r, min_c, max_r, max_c),
            'total_cells': total_cells,
            'actual_cells': actual_cells,
            'fill_ratio': fill_ratio,
            'missing_cells': total_cells - actual_cells
        })
    return bbox_info

for color in [0, 2, 8]:
    print(f"\n\n--- Color {color} ---")
    info = get_bbox_and_fill_ratio(grid, color)
    for item in info:
