# Based on analysis: fill missing cells in bbox for components

def copy_grid(grid):
    return [row[:] for row in grid]

def get_components(grid, color):
    positions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                positions.append((r, c))

    visited = set()
    components = []
    for pos in positions:
        if pos not in visited:
            comp = []
            queue = [pos]
            while queue:
                cr, cc = queue.pop(0)
                if (cr, cc) not in visited:
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
