                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))
            components.append(comp)
    return components

def get_bbox(component):
    rows = [r for r, c in component]
    cols = [c for r, c in component]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)
    return (min_r, min_c, max_r, max_c)

def is_filled_rectangle(grid, color, component):
    """Check if the bbox forms a complete rectangle of this color"""
    r_min, c_min, r_max, c_max = get_bbox(component)
    expected_cells = set((r, c) for r in range(r_min, r_max+1) 
                         for c in range(c_min, c_max+1))
    actual_cells = set(component)
    missing = expected_cells - actual_cells
    return len(missing) == 0, missing

